CREATE TABLE IF NOT EXISTS branches (id SERIAL PRIMARY KEY, name TEXT NOT NULL, delivery_fee INTEGER NOT NULL DEFAULT 150000 CHECK(delivery_fee>=0), scoop_grams INTEGER NOT NULL DEFAULT 100 CHECK(scoop_grams>0));
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','cashier')), branch_id INTEGER NOT NULL REFERENCES branches(id), active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS categories (id SERIAL PRIMARY KEY, name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS products (id SERIAL PRIMARY KEY, branch_id INTEGER NOT NULL REFERENCES branches(id), category_id INTEGER NOT NULL REFERENCES categories(id), name TEXT NOT NULL, price INTEGER NOT NULL CHECK(price>=0), grams INTEGER NOT NULL DEFAULT 0 CHECK(grams>=0), scoops INTEGER NOT NULL DEFAULT 0 CHECK(scoops>=0), max_flavors INTEGER NOT NULL DEFAULT 0 CHECK(max_flavors>=0), stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0), active BOOLEAN NOT NULL DEFAULT true, kind TEXT NOT NULL DEFAULT 'tub' CHECK(kind IN ('tub','cone','wafer','ice')));
CREATE TABLE IF NOT EXISTS flavors (id SERIAL PRIMARY KEY, branch_id INTEGER NOT NULL REFERENCES branches(id), name TEXT NOT NULL, family TEXT NOT NULL, stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0), active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS cash_sessions (id SERIAL PRIMARY KEY, branch_id INTEGER NOT NULL REFERENCES branches(id), opened_by INTEGER NOT NULL REFERENCES users(id), opened_at TIMESTAMPTZ NOT NULL DEFAULT now(), opening INTEGER NOT NULL CHECK(opening>=0), closed_at TIMESTAMPTZ, counted INTEGER, expected INTEGER);
CREATE UNIQUE INDEX IF NOT EXISTS one_open_cash ON cash_sessions(branch_id) WHERE closed_at IS NULL;
CREATE TABLE IF NOT EXISTS orders (id SERIAL PRIMARY KEY, request_key TEXT NOT NULL, branch_id INTEGER NOT NULL REFERENCES branches(id), user_id INTEGER NOT NULL REFERENCES users(id), cash_id INTEGER NOT NULL REFERENCES cash_sessions(id), channel TEXT NOT NULL CHECK(channel IN ('local','delivery')), status TEXT NOT NULL DEFAULT 'pending', customer JSONB NOT NULL DEFAULT '{}', notes TEXT NOT NULL DEFAULT '', items JSONB NOT NULL, consumption JSONB NOT NULL, subtotal INTEGER NOT NULL, delivery INTEGER NOT NULL, total INTEGER NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), cancellation TEXT, UNIQUE(branch_id, request_key));
CREATE TABLE IF NOT EXISTS payments (id SERIAL PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), cash_id INTEGER NOT NULL REFERENCES cash_sessions(id), method TEXT NOT NULL CHECK(method IN ('cash','qr','card')), amount INTEGER NOT NULL CHECK(amount>0), received INTEGER, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cash_movements (id SERIAL PRIMARY KEY, cash_id INTEGER NOT NULL REFERENCES cash_sessions(id), user_id INTEGER NOT NULL REFERENCES users(id), order_id INTEGER REFERENCES orders(id), amount INTEGER NOT NULL, reason TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS refunds (id SERIAL PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), cash_id INTEGER NOT NULL REFERENCES cash_sessions(id), method TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS stock_movements (id SERIAL PRIMARY KEY, branch_id INTEGER NOT NULL REFERENCES branches(id), user_id INTEGER NOT NULL REFERENCES users(id), target TEXT NOT NULL, target_id INTEGER NOT NULL, amount INTEGER NOT NULL, reason TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit (id SERIAL PRIMARY KEY, branch_id INTEGER NOT NULL REFERENCES branches(id), user_id INTEGER NOT NULL REFERENCES users(id), action TEXT NOT NULL, detail JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_requests (request_key TEXT PRIMARY KEY, branch_id INTEGER NOT NULL REFERENCES branches(id), order_id INTEGER NOT NULL REFERENCES orders(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
